(() => {
  'use strict';
  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const state = { user: null, csrf: '', view: 'dashboard', module: '', rows: [], metrics: null, query: '', caseTab: 'cases', modalRecord: null };
  const titles = { dashboard: 'Overview', my_profile: 'My profile', residents: 'Residents', documents: 'Documents & fees', cases: 'Cases & hearings', displacements: 'Disaster response', shelters: 'Shelter locations', relief: 'Relief distribution', health: 'Health records', medicines: 'Medicine inventory', aid: 'Financial assistance', staff: 'System admin', audit: 'Activity log' };
  const roleLabels={admin:'System Admin',captain:'Barangay Captain',secretary:'Secretary',health_worker:'Health Worker',tanod:'Tanod',als_teacher:'ALS Teacher',resident:'Barangay Residents'};
  const config = {
    residents: { title: 'Residents', singular: 'resident profile', desc: 'Keep household and demographic records current.', icon: '◎', columns: [['resident_code','ID'],['name','Resident'],['household_code','Household'],['purok','Purok'],['sectors','Sectors'],['status','Status']], fields: [
      ['first_name','First name','text',1],['middle_name','Middle name'],['last_name','Last name','text',1],['suffix','Suffix'],['birth_date','Date of birth','date'],['gender','Gender','select',['Prefer not to say','Female','Male','Other']],['civil_status','Civil status','select',['Single','Married','Widowed','Separated']],['occupation','Occupation'],['phone','Mobile number'],['email','Email','email'],['purok','Purok'],['address','Current address','textarea'],['photo','Official photo','file'],['household_code','Household code'],['household_role','Household role','select',['Head','Spouse','Child','Parent','Other']],['voter_status','Registered voter','select',[['0','No'],['1','Yes']]],['sectors','Sector classifications','multiselect',['Senior Citizen','PWD','Solo Parent','4Ps Beneficiary','Youth','Indigenous People']],['notes','Notes','textarea'],['status','Record status','select',['Active','Moved','Deceased']]
    ] },
    documents: { title: 'Documents & fees', singular: 'document request', desc: 'Prepare clearances and certificates, record fees, and verify releases.', icon: '▤', columns: [['document_no','Document no.'],['resident_name','Resident'],['document_type','Document'],['purpose','Purpose'],['fee','Fee'],['or_no','OR no.'],['status','Status'],['issued_at','Issued']], fields: [
      ['resident_name','Resident full name','text',1],['resident_id','Link resident profile','select','residents',false],['document_type','Document type','select',['Barangay Clearance','Certificate of Indigency','Certificate of Residency','First Time Job Seeker','Other'],1],['purpose','Purpose','text',1],['fee','Fee (₱)','number',1],['or_no','Official receipt no.'],['status','Request status','select',['Pending','Ready','Released','Cancelled'],1]
    ] },
    cases: { title: 'Cases & hearings', singular: 'case', desc: 'Track barangay complaints, mediation schedules, outcomes, and referrals.', icon: '⚖', columns: [['case_no','Case no.'],['case_type','Case type'],['complainant','Complainant'],['respondent','Respondent'],['status','Status'],['cfa_no','CFA no.'],['created_at','Filed']], fields: [
      ['case_type','Case type','select',['Neighbor dispute','Property boundary','Noise complaint','Debt / obligation','Family dispute','Public disturbance','Other'],1],['complainant','Complainant','text',1],['respondent','Respondent','text',1],['incident_date','Incident date','date'],['location','Incident location'],['narrative','Incident details','textarea'],['status','Case status','select',['Filed','For mediation','Scheduled','Settled','Referred','Closed'],1],['lupon_officer','Lupon officer'],['cfa_no','Certificate to File Action no.']
    ] },
    displacements: { title: 'Disaster response', singular: 'displacement record', desc: 'Track displaced families and monitor evacuation shelter occupancy.', icon: '⌂', columns: [['family_name','Family'],['family_size','Family size'],['origin_purok','Origin'],['shelter_id','Shelter'],['displaced_at','Displaced'],['returned_at','Returned']], fields: [
      ['family_name','Family / household name','text',1],['household_code','Household code'],['family_size','Number of family members','number',1],['origin_purok','Origin purok'],['shelter_id','Evacuation shelter','select','shelters'],['displaced_at','Displaced at','datetime-local'],['returned_at','Returned at','datetime-local'],['notes','Notes','textarea']
    ] },
    relief: { title: 'Relief distribution', singular: 'relief distribution', desc: 'Record packages by household and recipient sign-off to prevent duplicate claims.', icon: '♧', columns: [['reference_no','Reference'],['recipient_name','Recipient'],['household_code','Household'],['purok','Purok'],['package_type','Package'],['quantity','Qty'],['signature_name','Received by'],['distributed_at','Date']], fields: [
      ['recipient_name','Recipient name','text',1],['household_code','Household code','text',1],['purok','Purok'],['package_type','Relief package','select',['Family food pack','Hygiene kit','Drinking water','Baby care kit','Blanket set','Other'],1],['quantity','Quantity','number',1],['signature_name','Received / signed by']
    ] },
    health: { title: 'Health records', singular: 'health service record', desc: 'Log community health services and patient visits.', icon: '♡', columns: [['patient_name','Patient'],['service_type','Service'],['service_date','Date'],['health_worker','Health worker'],['details','Details']], fields: [
      ['patient_name','Patient full name','text',1],['service_type','Service type','select',['Immunization','Maternal checkup','Consultation','Medicine','Other']],['service_date','Service date','date',1],['details','Service notes','textarea'],['health_worker','Health worker']
    ] },
    medicines: { title: 'Medicine inventory', singular: 'medicine item', desc: 'Monitor essential supplies, expiry dates, and items for reorder.', icon: '＋', columns: [['name','Medicine'],['category','Category'],['quantity','On hand'],['unit','Unit'],['reorder_level','Reorder at'],['expiry_date','Expiry']], fields: [
      ['name','Medicine name','text',1],['category','Category'],['quantity','Quantity on hand','number',1],['unit','Unit','select',['tablets','capsules','bottles','packs','vials','units']],['reorder_level','Reorder threshold','number',1],['expiry_date','Expiry date','date']
    ] },
    shelters: { title: 'Shelter locations', singular: 'shelter location', desc: 'Set evacuation center locations and monitor their family capacity.', icon: '⌂', columns: [['name','Shelter'],['location','Location'],['capacity','Capacity'],['occupied','People inside'],['status','Status']], fields: [
      ['name','Shelter name','text',1],['location','Location / purok'],['latitude','Map latitude','number'],['longitude','Map longitude','number'],['capacity','People capacity','number',1],['occupied','Current occupancy','number',1],['status','Shelter status','select',['Open','Full','Closed'],1]
    ] },
    aid: { title: 'Financial assistance', singular: 'assistance distribution', desc: 'Manage local and DSWD aid with program details and recipient sign-offs.', icon: '₱', columns: [['reference_no','Reference'],['recipient_name','Recipient'],['household_code','Household'],['aid_program','Program'],['amount','Amount'],['assistance_date','Date'],['signed_by','Signed by']], fields: [
      ['recipient_name','Recipient name','text',1],['household_code','Household code'],['aid_program','Program / assistance type','text',1],['amount','Amount (₱)','number',1],['assistance_date','Distribution date','date',1],['signed_by','Received / signed by'],['notes','Notes','textarea']
    ] },
    hearings: { title: 'Hearings', singular: 'hearing schedule', desc: 'Schedule mediation, conciliation, arbitration, and follow-ups.', icon: '▦', columns: [['case_no','Case no.'],['complainant','Complainant'],['respondent','Respondent'],['hearing_type','Type'],['hearing_at','Schedule'],['venue','Venue'],['status','Status']], fields: [
      ['case_id','Case','select','cases'],['hearing_type','Hearing type','select',['Mediation','Conciliation','Arbitration','Follow-up']],['hearing_at','Date and time','datetime-local',1],['venue','Venue'],['status','Status','select',['Scheduled','Completed','Rescheduled','Cancelled']],['outcome','Outcome'],['notes','Notes','textarea']
    ] }
  };
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const initials = name => (name || 'SJ').split(/\s+/).slice(0,2).map(x => x[0] || '').join('').toUpperCase();
  const money = value => new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP',maximumFractionDigits:0}).format(Number(value || 0));
  const dateFmt = (value, opts = {month:'short',day:'numeric',year:'numeric'}) => value ? new Date(String(value).replace(' ','T')).toLocaleDateString('en-PH',opts) : '—';
  const dtFmt = value => value ? new Date(String(value).replace(' ','T')).toLocaleString('en-PH',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}) : '—';
  async function api(action, params = {}, body = null) {
    const url = new URL('api.php', location.href); url.searchParams.set('action', action); Object.entries(params).forEach(([k,v]) => url.searchParams.set(k,v));
    const headers = {'Accept':'application/json'}; if (body) { if(!(body instanceof FormData)) headers['Content-Type']='application/json'; if(state.csrf) headers['X-CSRF-Token']=state.csrf; }
    const res = await fetch(url, {method:body ? 'POST' : 'GET',headers,body:body ? (body instanceof FormData?body:JSON.stringify(body)) : undefined,credentials:'same-origin'});
    let data; try { data=await res.json(); } catch { data={error:'The server returned an unexpected response.'}; }
    if(!res.ok) { if(res.status===401&&state.user&&action!=='login'){state.user=null;state.csrf='';loginScreen(true);} const err=new Error(data.error || 'Something went wrong.'); err.status=res.status; throw err; }
    return data;
  }
  function toast(message, type='success') { const el=document.createElement('div'); el.className=`toast ${type}`; el.innerHTML=`<span>${type==='success'?'✓':'!'}</span>${esc(message)}`; $('#toastRoot').append(el); setTimeout(()=>el.remove(),3800); }
  function loginScreen(show=true) { $('#loginScreen').classList.toggle('hidden',!show); $('#registerScreen')?.classList.add('hidden'); $('#appShell').classList.toggle('hidden',show); }
  async function signIn(event) { event.preventDefault(); const form=new FormData(event.currentTarget); $('#loginError').classList.add('hidden'); const button=$('button',event.currentTarget); button.disabled=true; button.textContent='Signing in…'; try { const result=await api('login',{},Object.fromEntries(form)); state.user=result.user; state.csrf=result.csrf; showApp(); } catch(e) { $('#loginError').textContent=e.message; $('#loginError').classList.remove('hidden'); } finally { button.disabled=false; button.innerHTML='Sign in <span>→</span>'; } }
  async function registerUser(event){event.preventDefault();const form=event.currentTarget;const fd=new FormData(form);const body=Object.fromEntries(fd);body.sectors=fd.getAll('sectors[]');delete body['sectors[]'];$('#registerError').classList.add('hidden');const button=$('button.primary-btn',form);button.disabled=true;button.textContent='Creating account…';try{const result=await api('register',{},body);state.user=result.user;state.csrf=result.csrf;toast('Resident account created.');await showApp();}catch(e){$('#registerError').textContent=e.message;$('#registerError').classList.remove('hidden');}finally{button.disabled=false;button.innerHTML='Create resident account <span>→</span>';}}
  async function showApp() { const folders={admin:'systemadmin/',captain:'barangaycaptain/',secretary:'secretary/',health_worker:'healthworker/',tanod:'tanod/',als_teacher:'alsteacher/',resident:'barangayresidents/'};if(new URLSearchParams(location.search).get('workspace')!=='1'){location.href=folders[state.user.role]||'index.php';return;} $('#userName').textContent=state.user.name; $('#userAvatar').textContent=initials(state.user.name); $('#userRole').textContent=roleLabels[state.user.role]||state.user.role; $('#todayDate').textContent=new Date().toLocaleDateString('en-PH',{weekday:'short',month:'short',day:'numeric'}); loginScreen(false); applyRoleNav();const requested=new URLSearchParams(location.search).get('view');if(requested){await go(requested);return;}if(state.user.role==='resident')await go('my_profile');else if(state.user.role==='als_teacher')await renderRolePortal();else await go('dashboard'); }
  function applyRoleNav() { $$('#mainNav [data-roles]').forEach(el=>el.classList.toggle('hidden',!el.dataset.roles.split(',').includes(state.user.role))); }
  async function bootstrap() { try { const r=await api('me'); state.user=r.user; state.csrf=r.csrf; await showApp(); } catch { loginScreen(true); } }
  async function logout() { try { await api('logout'); } catch {} state.user=null;state.csrf='';$('#userDropdown').classList.add('hidden');loginScreen(true); }
  async function go(view) { state.view=view; state.query=''; $('#crumbCurrent').textContent=titles[view] || view; $$('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.view===view)); closeSidebar(); if(view==='my_profile')await renderResidentPortal();else if(view==='dashboard') await renderDashboard(); else if(view==='audit') await renderAudit(); else if(view==='staff') {location.href='systemadmin/';return;} else if(view==='cases') await renderCases(); else await renderModule(view); }
  function closeSidebar() { document.body.classList.remove('sidebar-open'); }
  function renderDashboardShell() { const today=new Date().toLocaleDateString('en-PH',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase();$('#pageContent').innerHTML=`<section class="page-heading"><div><p class="eyebrow">${today}</p><h1>Good day, ${esc((state.user.name||'').split(' ')[0])}<span class="heading-spark">✦</span></h1><p>Here's what's happening in your community today.</p></div><button class="secondary-btn" data-action="refresh">↻ &nbsp;Refresh overview</button></section><div id="dashboardBody"><div class="loading-state">Gathering your workspace…</div></div>`; }
  async function renderDashboard() {
    renderDashboardShell(); try { state.metrics=await api('metrics'); drawDashboard(state.metrics); } catch(e) { $('#dashboardBody').innerHTML=`<div class="empty-card"><div class="empty-icon">!</div><h3>Could not load overview</h3><p>${esc(e.message)}</p></div>`; }
  }
  function drawDashboard(m) {
    const cards=[['Registered residents',m.residents,'◎','blue',`${m.households.toLocaleString()} households`],['Open barangay cases',m.open_cases,'⚖','amber',m.open_cases?'Follow-up may be needed':'No active cases'],['Families displaced',m.displaced,'⌂','coral',`${Number(m.shelter_capacity.occupied||0)} of ${Number(m.shelter_capacity.capacity||0)} shelter spaces`],['Documents this month',m.documents_month,'▤','green',`${money(m.revenue_month)} fees recorded`]];
    const bars=m.puroks||[]; const max=Math.max(...bars.map(x=>Number(x.value)),1);
    $('#dashboardBody').innerHTML=`<div class="stats-grid">${cards.map(c=>`<article class="stat-card"><div class="stat-top"><span>${c[0]}</span><span class="stat-icon ${c[3]}">${c[2]}</span></div><strong class="stat-value">${Number(c[1]).toLocaleString()}</strong><span class="stat-foot"><b class="tiny-dot ${c[3]}"></b>${esc(c[4])}</span></article>`).join('')}</div><div class="dashboard-grid"><article class="panel demographics-panel"><div class="panel-head"><div><h2>Residents by purok</h2><p>Distribution across your community</p></div><button class="text-button" data-go="residents">View residents <span>→</span></button></div><div class="bar-chart">${bars.length?bars.map((b,i)=>`<div class="bar-row"><span class="bar-label">${esc(b.label)}</span><div class="bar-track"><span class="bar-fill fill-${i%5}" style="width:${Math.max(5,Number(b.value)/max*100)}%"></span></div><strong>${Number(b.value)}</strong></div>`).join(''):`<div class="empty-inline">Add resident profiles to see the household distribution.</div>`}</div><div class="chart-legend"><span><i></i> Active resident profiles</span><small>${m.residents.toLocaleString()} total</small></div></article><article class="panel hearings-panel"><div class="panel-head"><div><h2>Upcoming hearings</h2><p>Next scheduled sessions</p></div><button class="round-arrow" data-go="cases" aria-label="View hearings">↗</button></div><div class="hearing-list">${m.upcoming.length?m.upcoming.map(h=>`<div class="hearing-row"><div class="hearing-date"><b>${new Date(String(h.hearing_at).replace(' ','T')).getDate()}</b><span>${new Date(String(h.hearing_at).replace(' ','T')).toLocaleDateString('en-PH',{month:'short'})}</span></div><div class="hearing-info"><strong>${esc(h.case_no)} · ${esc(h.hearing_type)}</strong><small>${esc(h.complainant)} vs ${esc(h.respondent)}</small></div><span class="hearing-time">${new Date(String(h.hearing_at).replace(' ','T')).toLocaleTimeString('en-PH',{hour:'numeric',minute:'2-digit'})}</span></div>`).join(''):`<div class="empty-inline">No hearings on the calendar yet.</div>`}</div><button class="panel-link" data-go="cases">Open case calendar <span>→</span></button></article></div><div class="dashboard-grid lower-grid"><article class="panel residents-panel"><div class="panel-head"><div><h2>Recently added residents</h2><p>Latest profiles in your registry</p></div><button class="text-button" data-go="residents">See all <span>→</span></button></div>${m.recent_residents.length?`<div class="mini-table"><div class="mini-table-head"><span>RESIDENT</span><span>HOUSEHOLD / PUROK</span><span>ADDED</span></div>${m.recent_residents.map(r=>`<div class="mini-row"><div class="mini-person"><span class="avatar soft">${initials(r.first_name+' '+r.last_name)}</span><span><b>${esc(r.first_name)} ${esc(r.last_name)}</b><small>${esc(r.resident_code)}</small></span></div><span>${esc(r.purok||'—')}</span><span>${dateFmt(r.created_at)}</span></div>`).join('')}</div>`:`<div class="empty-inline padded">No profiles yet. Add your first resident to begin building the local registry.</div>`}</article><article class="panel quick-panel"><div class="panel-head"><div><h2>Quick actions</h2><p>Common front desk tasks</p></div></div><div class="quick-actions"><button data-new="residents"><span class="quick-icon blue">◎</span><span><b>Add resident</b><small>Create a resident profile</small></span><i>→</i></button><button data-new="documents"><span class="quick-icon green">▤</span><span><b>Issue a document</b><small>Start a certificate request</small></span><i>→</i></button><button data-new="cases"><span class="quick-icon amber">⚖</span><span><b>Log a complaint</b><small>Open a barangay case</small></span><i>→</i></button><button data-new="displacements"><span class="quick-icon coral">⌂</span><span><b>Record a displacement</b><small>Check in an evacuated family</small></span><i>→</i></button></div>${m.low_stock?`<div class="stock-alert"><span>!</span><div><b>${m.low_stock} medicine item${m.low_stock>1?'s':''} at reorder level</b><small>Review the health center inventory.</small></div><button data-go="medicines">→</button></div>`:''}</article></div>`;
  }
  async function loadRows(module,q='') { const result=await api('list',{module,q}); return result.items||[]; }
  const cellValue = (row,key,module) => {
    if(key==='name') return `<div class="mini-person">${row.photo_path?`<img class="avatar photo-avatar" src="${esc(row.photo_path)}" alt="">`:`<span class="avatar soft">${initials((row.first_name||'')+' '+(row.last_name||''))}</span>`}<span><b>${esc(row.first_name)} ${esc(row.middle_name?row.middle_name+' ':'')}${esc(row.last_name)}</b><small>${esc(row.phone||row.email||'No contact on file')}</small></span></div>`;
    if(key==='sectors') { let s=row.sectors; try { s=typeof s==='string'?JSON.parse(s||'[]'):s||[] } catch { s=[] } return s.length?s.slice(0,2).map(x=>`<span class="tag neutral">${esc(x)}</span>`).join(' '):'<span class="muted">—</span>'; }
    if(['created_at','issued_at','distributed_at','service_date','assistance_date','incident_date','expiry_date','displaced_at','returned_at'].includes(key)) return dateFmt(row[key]);
    if(key==='fee'||key==='amount') return money(row[key]);
    if(key==='shelter_id') return esc((state.shelters||[]).find(s=>s.id==row[key])?.name||'—');
    if(key==='voter_status') return Number(row[key])?'Yes':'No';
    if(key==='quantity') return `${esc(row.quantity)} ${esc(row.unit||'')}`.trim();
    if(key==='family_size') return `${esc(row.family_size)} people`;
    if(key==='status') return `<span class="status-pill ${String(row.status||'').toLowerCase().replaceAll(' ','-')}"><i></i>${esc(row.status)}</span>`;
    return esc(row[key]||'—');
  };
  function tableMarkup(module,rows,columns) {
    return `<div class="table-scroll"><table><thead><tr>${columns.map(c=>`<th>${esc(c[1])}</th>`).join('')}<th class="action-th">ACTIONS</th></tr></thead><tbody>${rows.map(row=>`<tr data-row-id="${row.id}">${columns.map(c=>`<td>${cellValue(row,c[0],module)}</td>`).join('')}<td><div class="row-actions"><button class="row-action" data-edit="${esc(module)}" data-id="${row.id}" title="Edit">✎</button>${module==='residents'?`<button class="row-action" data-history="${row.id}" title="Address history">◷</button>`:''}${module==='documents'?`<button class="row-action" data-print="${row.id}" title="Print certificate">▧</button>`:''}${module==='cases'?`<button class="row-action" data-schedule="${row.id}" title="Schedule hearing">＋</button>${row.cfa_no?`<button class="row-action" data-cfa="${row.id}" title="Print Certificate to File Action">▧</button>`:''}`:''}<button class="row-action danger" data-delete="${esc(module)}" data-id="${row.id}" title="Delete">×</button></div></td></tr>`).join('')}</tbody></table></div>`;
  }
  async function renderModule(module) {
    state.module=module; const cfg=config[module]; if(!cfg) return;
    if(module==='displacements') { try { state.shelters=(await api('shelters')).items; } catch {} }
    const tabs=module==='cases'?`<div class="view-tabs"><button class="view-tab ${state.caseTab==='cases'?'selected':''}" data-case-tab="cases">Cases</button><button class="view-tab ${state.caseTab==='hearings'?'selected':''}" data-case-tab="hearings">Hearing schedule</button></div>`:'';
    const shelterBlock=module==='displacements'?`<div class="shelter-heading"><div><b>Evacuation centers</b><small>Live occupancy from family check-ins</small></div><button class="text-button" data-go="shelters">Manage centers <span>→</span></button></div><section class="shelter-grid">${(state.shelters||[]).map(s=>{const pct=s.capacity?Math.min(100,Math.round(Number(s.occupied)/Number(s.capacity)*100)):0;const hasCoords=s.latitude!==null&&s.latitude!==''&&s.longitude!==null&&s.longitude!=='';const mapUrl=hasCoords?`https://www.openstreetmap.org/?mlat=${encodeURIComponent(s.latitude)}&mlon=${encodeURIComponent(s.longitude)}#map=16/${encodeURIComponent(s.latitude)}/${encodeURIComponent(s.longitude)}`:'';return `<article class="shelter-card"><div class="shelter-head"><div><small>EVACUATION CENTER</small><b>${esc(s.name)}</b><span>${esc(s.location||'Location not set')}</span>${mapUrl?`<a class="map-link" href="${esc(mapUrl)}" target="_blank" rel="noopener">⌖ Open location map</a>`:''}</div><span class="status-pill ${String(s.status).toLowerCase()}"><i></i>${esc(s.status)}</span></div><div class="shelter-occupancy"><div class="shelter-track"><i style="width:${pct}%"></i></div><b>${Number(s.occupied).toLocaleString()} <small>/ ${Number(s.capacity).toLocaleString()} people</small></b></div></article>`}).join('')}</section>`:'';
    $('#pageContent').innerHTML=`<section class="page-heading compact"><div><div class="section-icon ${module}">${cfg.icon}</div><div><p class="eyebrow">COMMUNITY RECORDS</p><h1>${cfg.title}</h1><p>${cfg.desc}</p></div></div><button class="primary-btn add-btn" data-new="${module==='cases'&&state.caseTab==='hearings'?'hearings':module}"><span>＋</span> ${module==='cases'&&state.caseTab==='hearings'?'Schedule hearing':'Add '+cfg.singular}</button></section>${tabs}${shelterBlock}<section class="module-toolbar"><div class="records-label"><b id="recordCount">—</b><span>records</span></div><div class="toolbar-right"><label class="search-box"><span>⌕</span><input id="tableSearch" type="search" placeholder="Search ${cfg.title.toLowerCase()}…"><kbd>⌘ K</kbd></label><button class="secondary-btn small" data-action="reload">↻ &nbsp;Refresh</button></div></section><div id="moduleTable" class="panel table-panel"><div class="loading-state">Loading ${cfg.title.toLowerCase()}…</div></div>`;
    $('#tableSearch').addEventListener('input',debounce(async e=>{state.query=e.target.value; await fillTable(module,state.query);},250)); await fillTable(module);
  }
  async function fillTable(module,q='') {
    const actual=module==='cases'&&state.caseTab==='hearings'?'hearings':module;
    try { const rows=await loadRows(actual,q); state.rows=rows; $('#recordCount').textContent=rows.length; const cols=actual==='hearings'?config.hearings.columns:config[module].columns; $('#moduleTable').innerHTML=rows.length?tableMarkup(actual,rows,cols):`<div class="empty-state"><div class="empty-art">${config[module].icon}</div><h3>No ${config[module].title.toLowerCase()} yet</h3><p>Use the button above to add the first record to this workspace.</p><button class="primary-btn" data-new="${actual}">＋ &nbsp;Add ${actual==='hearings'?'hearing':config[module].singular}</button></div>`; updateNavCounts(module,rows.length); }
    catch(e) { $('#moduleTable').innerHTML=`<div class="empty-state"><div class="empty-art">!</div><h3>We couldn't load these records</h3><p>${esc(e.message)}</p><button class="secondary-btn" data-action="reload">Try again</button></div>`; }
  }
  function updateNavCounts(module,count) { const key=module==='cases'?'cases':module; const el=$(`[data-count="${key}"]`); if(el) el.textContent=count||''; }
  let searchTimer; function debounce(fn,ms){return (...args)=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>fn(...args),ms);};}
  async function renderCases(){state.caseTab=state.caseTab||'cases'; await renderModule('cases');}
  async function renderResidentPortal(){state.view='my_profile';$('#crumbCurrent').textContent='My profile';$$('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.view==='my_profile'));$('#pageContent').innerHTML=`<section class="page-heading"><div><p class="eyebrow">BARANGAY RESIDENT PORTAL</p><h1>Welcome, ${esc((state.user.name||'').split(' ')[0])}</h1><p>Review the information saved to your resident profile.</p></div></section><div id="residentProfilePanel" class="panel resident-profile-panel"><div class="loading-state">Loading your profile…</div></div>`;try{const {profile:p}=await api('my_profile');let sectors=[];try{sectors=typeof p.sectors==='string'?JSON.parse(p.sectors||'[]'):p.sectors||[]}catch{};$('#residentProfilePanel').innerHTML=`<div class="profile-banner"><span class="avatar large-avatar">${initials(p.first_name+' '+p.last_name)}</span><div><p class="eyebrow">RESIDENT PROFILE · ${esc(p.resident_code)}</p><h2>${esc([p.first_name,p.middle_name,p.last_name,p.suffix].filter(Boolean).join(' '))}</h2><span class="profile-role">${roleLabels.resident}</span></div></div><div class="profile-grid"><div><small>EMAIL ADDRESS</small><b>${esc(p.email||'—')}</b></div><div><small>MOBILE NUMBER</small><b>${esc(p.phone||'—')}</b></div><div><small>DATE OF BIRTH</small><b>${p.birth_date?dateFmt(p.birth_date):'—'}</b></div><div><small>GENDER</small><b>${esc(p.gender||'—')}</b></div><div><small>CIVIL STATUS</small><b>${esc(p.civil_status||'—')}</b></div><div><small>OCCUPATION</small><b>${esc(p.occupation||'—')}</b></div><div><small>CURRENT ADDRESS</small><b>${esc(p.address||'—')}</b></div><div><small>PUROK</small><b>${esc(p.purok||'—')}</b></div><div><small>HOUSEHOLD</small><b>${esc(p.household_code||'—')} ${p.household_role?'· '+esc(p.household_role):''}</b></div><div><small>VOTER STATUS</small><b>${Number(p.voter_status)?'Registered':'Not registered / not indicated'}</b></div><div class="wide"><small>SECTOR CLASSIFICATIONS</small><b>${sectors.length?sectors.map(s=>`<span class="tag neutral">${esc(s)}</span>`).join(' '):'None selected'}</b></div></div><p class="profile-footnote">To correct your information or request a barangay document, please contact the barangay office.</p>`;}catch(e){$('#residentProfilePanel').innerHTML=`<div class="empty-state"><h3>Profile unavailable</h3><p>${esc(e.message)}</p></div>`;}}
  async function renderRolePortal(){state.view='dashboard';$('#crumbCurrent').textContent='My workspace';$('#pageContent').innerHTML=`<section class="page-heading"><div><p class="eyebrow">ALS TEACHER WORKSPACE</p><h1>Welcome, ${esc((state.user.name||'').split(' ')[0])}</h1><p>Your account role is managed by the San Juan system administrator.</p></div></section><div class="panel resident-profile-panel"><div class="empty-state"><div class="empty-art">✎</div><h3>ALS Teacher account</h3><p>Contact the system administrator if you need additional workspace access or a role change.</p></div></div>`;}
  async function renderStaff() {
    $('#pageContent').innerHTML=`<section class="page-heading compact"><div><div class="section-icon audit">♙</div><div><p class="eyebrow">SECURITY & OVERSIGHT</p><h1>Staff access</h1><p>Manage workspace accounts and role permissions.</p></div></div><button class="primary-btn" data-staff-new>＋ &nbsp;Add staff account</button></section><div class="notice-banner"><span>🔐</span><p><b>Access is role based.</b> Health workers can access health records; tanods can help with resident and response records. Only administrators can manage staff accounts.</p></div><section class="module-toolbar"><div class="records-label"><b id="staffCount">—</b><span>staff accounts</span></div><button class="secondary-btn small" data-action="staff-reload">↻ &nbsp;Refresh</button></section><div id="staffTable" class="panel table-panel"><div class="loading-state">Loading staff…</div></div>`;
    try { const result=await api('staff'); const rows=result.items||[]; $('#staffCount').textContent=rows.length; $('#staffTable').innerHTML=rows.length?`<div class="table-scroll"><table><thead><tr><th>STAFF MEMBER</th><th>USERNAME</th><th>ROLE</th><th>STATUS</th><th>ADDED</th><th class="action-th">ACTIONS</th></tr></thead><tbody>${rows.map(r=>`<tr><td><div class="mini-person"><span class="avatar soft">${initials(r.name)}</span><span><b>${esc(r.name)}</b><small>${Number(r.id)===Number(state.user.id)?'You':'Barangay staff'}</small></span></div></td><td>${esc(r.username)}</td><td><span class="role-badge">${esc(r.role.replaceAll('_',' '))}</span></td><td><span class="status-pill ${Number(r.active)?'active':'closed'}"><i></i>${Number(r.active)?'Active':'Inactive'}</span></td><td>${dateFmt(r.created_at)}</td><td><div class="row-actions"><button class="row-action" data-staff-edit="${r.id}" title="Edit access">✎</button><button class="row-action" data-staff-toggle="${r.id}" data-active="${Number(r.active)?0:1}" title="${Number(r.active)?'Deactivate':'Activate'}">${Number(r.active)?'◌':'✓'}</button></div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><h3>No staff accounts</h3><p>Add an account for each barangay staff member.</p></div>`; state.staffRows=rows; } catch(e) { $('#staffTable').innerHTML=`<div class="empty-state"><h3>Could not load staff accounts</h3><p>${esc(e.message)}</p></div>`; }
  }
  function openStaffForm(id=null) {
    const row=(state.staffRows||[]).find(r=>Number(r.id)===Number(id));
    $('#modalRoot').innerHTML=`<div class="modal-backdrop" data-close-modal><section class="modal-card staff-modal" role="dialog" aria-modal="true"><header class="modal-header"><div><p class="eyebrow">SECURITY & OVERSIGHT</p><h2>${id?'Edit staff access':'Add staff account'}</h2></div><button class="icon-btn" data-close-modal>×</button></header><form id="staffForm"><div class="modal-body"><div class="form-grid"><label class="form-field"><span>Full name<i>*</i></span><input name="name" required value="${esc(row?.name||'')}"></label><label class="form-field"><span>Username<i>*</i></span><input name="username" required minlength="3" maxlength="50" value="${esc(row?.username||'')}"></label><label class="form-field"><span>Role<i>*</i></span><select name="role" required>${[['admin','Administrator'],['captain','Barangay captain'],['secretary','Barangay secretary'],['health_worker','Health worker'],['tanod','Barangay tanod']].map(x=>`<option value="${x[0]}" ${row?.role===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label><label class="form-field"><span>${id?'New password':'Password'}${id?'':'<i>*</i>'}</span><input name="password" type="password" minlength="12" ${id?'':'required'} autocomplete="new-password" placeholder="${id?'Leave blank to keep current':'At least 12 characters'}"></label></div><p id="formError" class="form-error hidden"></p><p class="modal-private">Passwords are stored as secure hashes. Share credentials with the account holder privately.</p></div><footer class="modal-footer"><button type="button" class="secondary-btn" data-close-modal>Cancel</button><button class="primary-btn">Save account <span>→</span></button></footer></form></section></div>`;
    $('#staffForm').addEventListener('submit',async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget));if(id)body.id=Number(id);const btn=$('button.primary-btn',e.currentTarget);btn.disabled=true;btn.textContent='Saving…';try{await api('staff_save',{},body);$('#modalRoot').innerHTML='';toast('Staff access saved.');await renderStaff();}catch(err){$('#formError').textContent=err.message;$('#formError').classList.remove('hidden');btn.disabled=false;btn.textContent='Save account →';}});
    $('#modalRoot').addEventListener('click',e=>{if(e.target.hasAttribute('data-close-modal'))$('#modalRoot').innerHTML='';});
  }
  async function renderAudit() { $('#pageContent').innerHTML=`<section class="page-heading compact"><div><div class="section-icon audit">◷</div><div><p class="eyebrow">SECURITY & OVERSIGHT</p><h1>Activity log</h1><p>A chronological record of workspace actions.</p></div></div></section><section class="module-toolbar"><div class="records-label"><b>Recent</b><span>activity</span></div><button class="secondary-btn small" data-action="audit">↻ &nbsp;Refresh</button></section><div id="auditTable" class="panel table-panel"><div class="loading-state">Loading activity…</div></div>`; try {const r=await api('audit'); $('#auditTable').innerHTML=r.items.length?`<div class="table-scroll"><table><thead><tr><th>USER</th><th>ACTION</th><th>RECORD</th><th>RECORD ID</th><th>DATE & TIME</th></tr></thead><tbody>${r.items.map(a=>`<tr><td><b>${esc(a.username||'System')}</b></td><td><span class="audit-action">${esc(a.action)}</span></td><td>${esc(a.entity)}</td><td>${esc(a.entity_id||'—')}</td><td>${dtFmt(a.created_at)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state"><div class="empty-art">◷</div><h3>No activity recorded</h3><p>Workspace actions will appear here as they happen.</p></div>`;} catch(e){$('#auditTable').innerHTML=`<div class="empty-state"><h3>Could not load the activity log</h3><p>${esc(e.message)}</p></div>`;} }
  async function fieldOptions(field) { if(field[3]==='shelters'){const rows=(state.shelters||[]).length?state.shelters:(await api('shelters')).items;state.shelters=rows;return rows.map(x=>[x.id,`${x.name} · ${x.occupied}/${x.capacity}`]);} if(field[3]==='cases'){const rows=await loadRows('cases');return rows.map(x=>[x.id,`${x.case_no} · ${x.complainant} vs ${x.respondent}`]);} if(field[3]==='residents'){const rows=await loadRows('residents');state.residentOptions=rows;return rows.map(x=>[x.id,`${x.resident_code} · ${x.first_name} ${x.last_name}`]);} return field[3]||[]; }
  async function openForm(module,id=null,extras={}) {
    const cfg=config[module]; if(!cfg) return; let row=id?state.rows.find(r=>Number(r.id)===Number(id)):null;
    if(id&&!row){try{row=(await loadRows(module)).find(r=>Number(r.id)===Number(id));}catch{}}
    if(module==='hearings') state.shelters=state.shelters||[];
    const fields=cfg.fields; const title=id?`Edit ${cfg.singular}`:`Add ${cfg.singular}`;
    let fieldHtml=''; for(const f of fields){ const [name,label,type='text',arg4,arg5]=f; const required=type==='select'||type==='multiselect'?(arg5===undefined?true:arg5):arg4; const value=extras[name]??row?.[name]??''; let control='';
      if(type==='file') control=`<input name="photo" type="file" accept="image/jpeg,image/png,image/webp">${row?.photo_path?`<small class="photo-current">Current photo: <a href="${esc(row.photo_path)}" target="_blank" rel="noopener">View current image</a></small>`:''}`;
      else if(type==='textarea') control=`<textarea name="${name}" rows="3" ${required?'required':''} placeholder="Add details…">${esc(value)}</textarea>`;
      else if(type==='select'||type==='multiselect') { let opts=type==='select'?await fieldOptions(f):f[3]; if(type==='select'){ if(['voter_status'].includes(name)){opts=[['0','No'],['1','Yes']];} control=`<select name="${name}" ${required?'required':''}><option value="">Select…</option>${opts.map(o=>{const val=Array.isArray(o)?o[0]:o;const text=Array.isArray(o)?o[1]:o;return `<option value="${esc(val)}" ${String(value)===String(val)?'selected':''}>${esc(text)}</option>`}).join('')}</select>`;} else {let selected=[];try{selected=Array.isArray(value)?value:JSON.parse(value||'[]')}catch{} control=`<div class="check-options">${opts.map(o=>`<label class="check-option"><input type="checkbox" name="${name}[]" value="${esc(o)}" ${selected.includes(o)?'checked':''}><span>${esc(o)}</span></label>`).join('')}</div>`;} }
      else {let inputValue=value;if(type==='datetime-local'&&inputValue)inputValue=String(inputValue).replace(' ','T').slice(0,16);const numberAttrs=type!=='number'?'':(name==='latitude'||name==='longitude'?'step="any"':`min="0" step="${name==='fee'||name==='amount'?'0.01':'1'}"`);control=`<input name="${name}" type="${type}" value="${esc(inputValue)}" ${required?'required':''} ${numberAttrs} placeholder="${type==='date'?'':`Enter ${label.toLowerCase()}`}">`;}
      fieldHtml+=`<label class="form-field ${type==='textarea'||type==='multiselect'?'wide':''}"><span>${esc(label)}${required?'<i>*</i>':''}</span>${control}</label>`;
    }
    $('#modalRoot').innerHTML=`<div class="modal-backdrop" data-close-modal><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><header class="modal-header"><div><p class="eyebrow">${esc(cfg.title).toUpperCase()}</p><h2 id="modalTitle">${esc(title)}</h2></div><button class="icon-btn" data-close-modal aria-label="Close">×</button></header><form id="recordForm"><div class="modal-body"><div class="form-grid">${fieldHtml}</div><p id="formError" class="form-error hidden"></p><p class="modal-private">🔒 &nbsp;This record is saved to the private barangay workspace and logged for accountability.</p></div><footer class="modal-footer"><button type="button" class="secondary-btn" data-close-modal>Cancel</button><button class="primary-btn">${id?'Save changes':'Save record'} <span>→</span></button></footer></form></section></div>`;
    $('#recordForm').addEventListener('submit',e=>saveForm(e,module,id)); $('#recordForm').addEventListener('change',e=>{if(module==='documents'&&e.target.name==='resident_id'){const profile=(state.residentOptions||[]).find(x=>String(x.id)===e.target.value);if(profile)$('#recordForm').elements.resident_name.value=`${profile.first_name} ${profile.middle_name?profile.middle_name+' ':''}${profile.last_name}`;}}); $('#modalRoot').addEventListener('click',e=>{if(e.target.hasAttribute('data-close-modal')) $('#modalRoot').innerHTML='';}); setTimeout(()=>$('input,select,textarea',$('#recordForm'))?.focus(),50);
  }
  async function saveForm(e,module,id) { e.preventDefault(); const form=e.currentTarget;const data={};const photo=form.elements.photo?.files?.[0];for(const [k,v] of new FormData(form)){if(v instanceof File)continue;const name=k.endsWith('[]')?k.slice(0,-2):k;if(k.endsWith('[]')){data[name]=data[name]||[];data[name].push(v);}else data[name]=v;} if(id)data.id=id;
    if(['voter_status','shelter_id','case_id','family_size','quantity','reorder_level'].includes('')){}
    ['voter_status','shelter_id','case_id','family_size','quantity','reorder_level','latitude','longitude'].forEach(k=>{if(data[k]!==undefined&&data[k]!=='')data[k]=Number(data[k]);});
    ['fee','amount'].forEach(k=>{if(data[k]!==undefined)data[k]=Number(data[k]||0);});
    const btn=$('button.primary-btn',form);btn.disabled=true;btn.textContent='Saving…';try{let body={module,record:data};if(module==='residents'&&photo){body=new FormData();body.append('module',module);body.append('record',JSON.stringify(data));body.append('photo',photo);}await api('save',{},body);$('#modalRoot').innerHTML='';toast(`${config[module].singular} ${id?'updated':'saved'}.`); if(state.view==='dashboard') await renderDashboard();else if(module==='hearings'&&state.view==='cases') {state.caseTab='hearings';await renderCases();} else await renderModule(state.view);}catch(err){$('#formError').textContent=err.message.includes('uniq_relief_claim')?'This household has already received this package type.':err.message;$('#formError').classList.remove('hidden');btn.disabled=false;btn.textContent=id?'Save changes':'Save record';}}
  async function removeRecord(module,id){if(!confirm('Remove this record? This action will be added to the activity log.'))return;try{await api('delete',{}, {module,id:Number(id)});toast('Record removed.');if(state.view==='dashboard')await renderDashboard();else await renderModule(state.view);}catch(e){toast(e.message,'error');}}
  function printDocument(id) { const row=state.rows.find(r=>Number(r.id)===Number(id));if(!row)return;const base=location.href.substring(0,location.href.lastIndexOf('/')+1);const verify=`${base}api.php?action=verify&token=${encodeURIComponent(row.verification_token||'')}`;const w=window.open('','_blank','width=800,height=920');if(!w){toast('Allow pop-ups to print a document.','error');return;}w.document.write(`<!doctype html><html><head><title>${esc(row.document_type)} · ${esc(row.document_no)}</title><style>body{font:16px Georgia,serif;color:#18243b;margin:0;padding:50px}.sheet{max-width:680px;margin:auto;border:8px double #173c56;padding:48px;text-align:center;min-height:760px;box-sizing:border-box}.seal{font-size:54px;color:#126b64}.small{font:12px Arial,sans-serif;letter-spacing:2px;color:#6e7e8d}.title{font-size:26px;margin:35px 0 6px}.doc{font:13px Arial;color:#6e7e8d}.body{font-size:19px;line-height:1.9;text-align:justify;margin:60px 12px}.sig{display:flex;justify-content:space-around;margin-top:80px}.sig div{border-top:1px solid #667;padding:8px 16px}.qr{margin:24px auto 0;width:110px;height:110px}.verify{font:10px Arial;color:#667;word-break:break-all}@media print{body{padding:0}.sheet{border-width:7px}}</style></head><body><div class="sheet"><div class="seal">✦</div><div class="small">REPUBLIC OF THE PHILIPPINES · BARANGAY SAN JUAN</div><div class="small">OFFICE OF THE PUNONG BARANGAY</div><h1 class="title">${esc(row.document_type)}</h1><div class="doc">Document no. ${esc(row.document_no)}</div><div class="body">TO WHOM IT MAY CONCERN:<br><br>This is to certify that <b>${esc(row.resident_name)}</b>, a resident of Barangay San Juan, is hereby issued this ${esc(row.document_type.toLowerCase())}${row.purpose?` for the purpose of <b>${esc(row.purpose)}</b>`:''}.<br><br>Issued this ${dateFmt(row.issued_at||new Date().toISOString())} at Barangay San Juan, Philippines.</div><div class="sig"><div>Barangay Secretary</div><div>Punong Barangay</div></div><div id="qrcode" class="qr"></div><div class="verify">Scan to verify · ${esc(verify)}</div></div><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"><\/script><script>if(window.QRCode)new QRCode(document.getElementById('qrcode'),{text:${JSON.stringify(verify)},width:110,height:110});setTimeout(()=>window.print(),800);<\/script></body></html>`);w.document.close();}
  function printCfa(id) {const c=state.rows.find(x=>Number(x.id)===Number(id));if(!c?.cfa_no)return;const w=window.open('','_blank','width=800,height=900');if(!w){toast('Allow pop-ups to print a certificate.','error');return;}w.document.write(`<!doctype html><html><head><title>Certificate to File Action · ${esc(c.cfa_no)}</title><style>body{font:17px Georgia,serif;color:#213544;padding:45px}.sheet{max-width:700px;min-height:780px;margin:auto;padding:55px;border:7px double #24564f;text-align:center;box-sizing:border-box}.small{font:12px Arial,sans-serif;letter-spacing:1.8px;color:#71827f}.seal{font-size:48px;color:#28766b}.title{font-size:25px;margin:30px 0 4px}.number{font:12px Arial;color:#687a80}.copy{text-align:justify;line-height:1.9;margin:70px 8px;font-size:18px}.signature{margin:95px auto 0;border-top:1px solid #546a6a;width:230px;padding-top:8px;font-size:14px}@media print{body{padding:0}}</style></head><body><div class="sheet"><div class="seal">✦</div><div class="small">REPUBLIC OF THE PHILIPPINES · BARANGAY SAN JUAN</div><div class="small">OFFICE OF THE LUPONG TAGAPAMAYAPA</div><h1 class="title">CERTIFICATE TO FILE ACTION</h1><div class="number">${esc(c.cfa_no)} · Case ${esc(c.case_no)}</div><div class="copy">This is to certify that a complaint involving <b>${esc(c.complainant)}</b>, complainant, and <b>${esc(c.respondent)}</b>, respondent, was brought before the Lupong Tagapamayapa of Barangay San Juan. The parties were given the opportunity to settle the dispute through barangay conciliation. The matter remains unresolved and may be brought before the proper court or government office, subject to applicable law and procedure.<br><br>Issued this ${dateFmt(new Date().toISOString())} at Barangay San Juan, Philippines.</div><div class="signature">Punong Barangay / Lupon Chairperson</div></div><script>setTimeout(()=>window.print(),400)<\/script></body></html>`);w.document.close();}
  function openHearing(caseId){openForm('hearings',null,{case_id:String(caseId),hearing_type:'Mediation',status:'Scheduled'});}
  async function openAddressHistory(residentId){try{const r=await api('address_history',{resident_id:residentId});const person=state.rows.find(x=>Number(x.id)===Number(residentId));$('#modalRoot').innerHTML=`<div class="modal-backdrop" data-close-modal><section class="modal-card" role="dialog" aria-modal="true"><header class="modal-header"><div><p class="eyebrow">RESIDENT RECORD</p><h2>Address history · ${esc(person?person.first_name+' '+person.last_name:'Resident')}</h2></div><button class="icon-btn" data-close-modal>×</button></header><div class="modal-body"><div class="history-list">${r.items.length?r.items.map(x=>`<article class="history-item"><span class="history-dot"></span><div><b>${esc(x.address)}</b><small>${esc(x.purok||'Purok not recorded')} · ${x.moved_in?dateFmt(x.moved_in):dateFmt(x.created_at)}${x.moved_out?` – ${dateFmt(x.moved_out)}`:' · Current record'}</small></div></article>`).join(''):`<div class="empty-inline">No address history recorded.</div>`}</div></div><footer class="modal-footer"><button class="secondary-btn" data-close-modal>Close</button></footer></section></div>`;$('#modalRoot').addEventListener('click',e=>{if(e.target.hasAttribute('data-close-modal'))$('#modalRoot').innerHTML='';});}catch(e){toast(e.message,'error');}}
  document.addEventListener('click',async e=>{
    const nav=e.target.closest('.nav-item[data-view]');if(nav){await go(nav.dataset.view);return;}
    const goBtn=e.target.closest('[data-go]');if(goBtn){await go(goBtn.dataset.go);return;}
    const add=e.target.closest('[data-new]');if(add){await openForm(add.dataset.new);return;}
    const edit=e.target.closest('[data-edit]');if(edit){await openForm(edit.dataset.edit,edit.dataset.id);return;}
    const del=e.target.closest('[data-delete]');if(del){await removeRecord(del.dataset.delete,del.dataset.id);return;}
    const pr=e.target.closest('[data-print]');if(pr){printDocument(pr.dataset.print);return;}
    const cfa=e.target.closest('[data-cfa]');if(cfa){printCfa(cfa.dataset.cfa);return;}
    const history=e.target.closest('[data-history]');if(history){await openAddressHistory(history.dataset.history);return;}
    const sched=e.target.closest('[data-schedule]');if(sched){openHearing(sched.dataset.schedule);return;}
    const tab=e.target.closest('[data-case-tab]');if(tab){state.caseTab=tab.dataset.caseTab;await renderCases();return;}
    if(e.target.closest('[data-staff-new]')){openStaffForm();return;}
    const staffEdit=e.target.closest('[data-staff-edit]');if(staffEdit){openStaffForm(staffEdit.dataset.staffEdit);return;}
    const staffToggle=e.target.closest('[data-staff-toggle]');if(staffToggle){const id=Number(staffToggle.dataset.staffToggle);if(!confirm(`${Number(staffToggle.dataset.active)?'Activate':'Deactivate'} this staff account?`))return;try{await api('staff_status',{}, {id,active:Number(staffToggle.dataset.active)});toast('Staff account status updated.');await renderStaff();}catch(err){toast(err.message,'error');}return;}
    const reload=e.target.closest('[data-action]');if(reload){if(reload.dataset.action==='audit')await renderAudit();else if(reload.dataset.action==='staff-reload')await renderStaff();else if(state.view==='dashboard')await renderDashboard();else if(state.module)await fillTable(state.module,state.query);return;}
  });
  $('#loginForm').addEventListener('submit',signIn);$('#registerForm').addEventListener('submit',registerUser);$('#showRegister').addEventListener('click',()=>{$('#loginScreen').classList.add('hidden');$('#registerScreen').classList.remove('hidden');window.scrollTo(0,0);});$('#backToLogin').addEventListener('click',()=>{ $('#registerScreen').classList.add('hidden');$('#loginScreen').classList.remove('hidden');window.scrollTo(0,0);});$('#logoutBtn').addEventListener('click',logout);$('#menuToggle').addEventListener('click',()=>document.body.classList.toggle('sidebar-open'));$('#sidebarClose').addEventListener('click',closeSidebar);$('#sidebarShade').addEventListener('click',closeSidebar);$('#userMenu').addEventListener('click',()=>$('#userDropdown').classList.toggle('hidden'));document.addEventListener('click',e=>{if(!e.target.closest('#userMenu')&&!e.target.closest('#userDropdown'))$('#userDropdown').classList.add('hidden');});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#tableSearch')?.focus();}if(e.key==='Escape')$('#modalRoot').innerHTML='';});
  bootstrap();
})();
